import { mockGroups } from "./inventoryMockData";
import { objectViolatesPolicy, type EvalGroup } from "@/lib/policyEval";

export interface SSHEndpoint {
  host: string;
  ip: string;
  port: number;
  role: "client" | "host";
  lastSeen: string;
}

export interface AgentMeta {
  agentType: "Autonomous Agent" | "Copilot" | "Service Bot" | "MCP Server" | "Orchestrator" | "Pipeline Agent";
  framework: string;
  servicesAccessed: string[];
  permissions: string[];
  permissionRisk: "Over-privileged" | "Right-sized" | "Minimal";
  lastActivity: string;
  actionsPerDay: number;
  mcpTools?: string[];
}

export interface CryptoAsset {
  id: string;
  name: string;
  type:
    | "TLS Certificate"
    | "SSH Key"
    | "SSH Certificate"
    | "Code-Signing Certificate"
    | "K8s Workload Cert"
    | "Encryption Key"
    | "API Key / Secret"
    | "Cloud KMS Key"
    | "HSM Key";
  commonName: string;
  caIssuer: string;
  algorithm: string;
  keyLength: string;
  serial: string;
  owner: string;
  team: string;
  application: string;
  environment: "Production" | "Staging" | "Development";
  infrastructure: string;
  discoverySource: string;
  issueDate: string;
  expiryDate: string;
  daysToExpiry: number;
  lastRotated: string;
  autoRenewal: boolean;
  rotationFrequency: string;
  status: "Active" | "Healthy" | "Expiring" | "Expired" | "Revoked" | "Pending" | "Orphaned";
  pqcRisk: "Critical" | "High" | "Medium" | "Low" | "Safe";
  policyViolations: number;
  dependencyCount: number;
  tags: string[];
  sshEndpoints?: SSHEndpoint[];
  agentMeta?: AgentMeta;
  // ── Policy-evaluation enrichment (optional; populated for some objects) ──
  signatureAlgorithm?: "SHA-1" | "SHA-256" | "SHA-384" | "SHA-512" | "MD5";
  isSelfSigned?: boolean;
  revocationStatus?: "Valid" | "Revoked" | "Unknown";
  protocolVersion?: "TLS 1.0" | "TLS 1.1" | "TLS 1.2" | "TLS 1.3";
  cipherSuite?: string;
  protectionLevel?: "HSM-Protected" | "Software-Protected";
  // ── Asset ↔ Group membership & derived policy verdicts ──
  groupIds?: string[];
  violatedPolicyIds?: string[];

  // Type-specific enterprise attributes (optional; never read by the risk engine).
  cert?: {
    subjectO?: string;
    subjectOU?: string;
    subjectL?: string;
    subjectST?: string;
    subjectC?: string;
    issuerDN?: string;
    sans?: string[];
    keyUsage?: string[];
    extendedKeyUsage?: string[];
    basicConstraints?: string;
    subjectKeyId?: string;
    authorityKeyId?: string;
    thumbprint?: string;
    endpoints?: { host: string; ip: string; port: number }[];
    complianceStatus?: "Compliant" | "Non-Compliant";
  };
  sshCert?: {
    principals?: string[];
    signingCA?: string;
    keyType?: "User" | "Host";
    criticalOptions?: string[];
    extensions?: string[];
    keyId?: string;
    associatedKeyName?: string;
  };
  sshKey?: {
    fingerprint?: string;
    associatedUsers?: { ip: string; user: string }[];
    filePaths?: string[];
    clientEndpoints?: string[];
    hostEndpoints?: string[];
    complianceGroup?: string;
    managementStatus?: "Managed" | "Monitored";
    riskStatus?: "Shared" | "Weak" | "Rogue" | "Misplaced" | "Suspicious" | "Clean";
    ageDays?: number;
  };
  encKey?: {
    protection?: "HSM" | "Cloud KMS" | "Software";
    store?: string;
    purpose?: string;
    keyState?: "Enabled" | "Disabled";
    exportable?: boolean;
    cryptoperiod?: string;
    wrappedBy?: string;
  };
  cloudKey?: {
    cloudProvider?: "AWS" | "Azure";
    region?: string;
    keyManager?: "Customer-Managed" | "Provider-Managed";
    protectionLevel?: "Software" | "HSM" | "External HSM" | "CloudHSM";
    keyState?: "Enabled" | "Disabled" | "PendingDeletion";
    rotationEnabled?: boolean;
    rotationInterval?: number;
    daysSinceRotation?: number;
    expirationSet?: boolean;
    publicAccess?: boolean;
    wildcardDecrypt?: boolean;
    deletionProtection?: boolean;
    auditLogging?: boolean;
    keyRef?: string;
    purpose?: string;
  };
  hsmKey?: {
    hsmVendor?: "Utimaco" | "Crypto4A";
    moduleModel?: string;
    partition?: string;
    slot?: string;
    keyClass?: "Public" | "Private" | "Secret";
    keyState?: "Active" | "Inactive" | "Destroyed" | "Archived";
    purpose?: string;
    extractable?: boolean;
    sensitive?: boolean;
    neverExtractable?: boolean;
    alwaysSensitive?: boolean;
    usageFlags?: string[];
    fipsMode?: "FIPS-Approved" | "Non-FIPS";
    startDate?: string;
    endDate?: string;
    label?: string;
  };
  secret?: {
    secretType?: string;
    store?: string;
    secretPath?: string;
    lastUsed?: string;
    version?: string;
    exposure?: "Not detected" | "Code repo" | "CI/CD" | "Log";
    consumers?: string[];
    noExpiry?: boolean;
  };
}

