// Helpers to keep OOB condition shapes consistent with ConditionBuilder.
const _g = (id: string, innerLogic: "AND" | "OR", rows: { field: string; operator: string; value: string }[]) => ({
  id,
  innerLogic,
  rows: rows.map((r, i) => ({ id: `${id}-r${i}`, ...r })),
});

